{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 동물보호센터의 유기동물 보호담당자를 아무나 맡을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "아무나 맡을 수 없습니다. 서울특별시 동물보호 조례 제13조제1항은 구청장 또는 동물보호센터의 장이 유기동물 보호담당자를 지정하여 보호·관리하게 하여야 한다고 정하고, 그 보호담당자는 같은 항 각 호의 어느 하나에 해당하는 자로 한정됩니다. 그 각 호는 ① 고등학교 이상의 학교에서 동물보호 또는 동물복지과목이 포함된 동물관련 분야를 전공한 자, ② 동물보호 정부기관 또는 민간시설에서 1년 이상 해당 동물에 대한 사육경험이 있는 자입니다.",
          "b_ids": "동물보호:제13조제1항, 동물보호:제13조제1항제1호, 동물보호:제13조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
